INSERT OR IGNORE INTO records
(record_no, title, region, record_type, risk_level, status, assigned_to, summary, content, is_published)
VALUES
('RY-2026-014', '새벽마다 두 번 울리는 전화기', '인천', '物件 / 記錄', '기록 오염', '회수 완료', '探-14 / 硏-03 / 護-08', '전원이 분리된 뒤에도 매일 같은 시각 두 차례 울리는 유선전화기.', '최초 신고자는 철거 예정 건물의 관리인이었다. 전화선과 전원은 모두 분리되어 있었으나 매일 03시 12분과 03시 19분에 벨이 울렸다. 수화기에서는 통화음 대신 낮은 숨소리와 종이를 넘기는 소리가 확인되었다. 현재 원본은 회수되었으며 음성 기록은 별도 보관 중이다.', 1),
('RY-2024-031', '철거 예정 주택의 가족사진', '부천', '物件', '접근 제한', '분석 중', '探-09 / 硏-03 / 護-01', '사진 속 인원과 실제 거주 이력이 일치하지 않는 가족사진.', '철거 전 잔존물 조사 중 발견되었다. 사진의 배경은 해당 주택 내부와 일치하지만 촬영된 가족의 신원은 확인되지 않았다. 열람자가 사진 속 빈자리를 오래 바라볼 경우 인원수가 달라졌다고 진술하는 사례가 반복되었다.', 1),
('RY-2019-008', '제목 없음', '서울', '記錄 / 傳染', '인명 위험', '열람 금지', '', '원문 열람이 제한된 기록형 이상.', '현재 공개 가능한 본문이 없다.', 0),
('RY-1912-000', '[결락 12자]', '미상', '未分類', '평가 불가', '회수 기록 없음', '記錄官', '최초 이관 목록에서 발견된 결락 기록.', '본문이 존재하지 않거나 회수 이전에 제거된 것으로 추정된다.', 1);
